-- Export read-only aggregate tables for BI use.
-- Run with psql connected to kkbox_analytics.
-- v1 and v2 remain separate through source_version; no detail rows are exported.

\copy (SELECT 'v1' AS source_version, transaction_month, COUNT(*) AS transaction_count, COUNT(DISTINCT msno) AS distinct_user_count, SUM(actual_amount_paid) AS transaction_record_amount FROM transactions_v1 GROUP BY transaction_month UNION ALL SELECT 'v2' AS source_version, transaction_month, COUNT(*) AS transaction_count, COUNT(DISTINCT msno) AS distinct_user_count, SUM(actual_amount_paid) AS transaction_record_amount FROM transactions_v2 GROUP BY transaction_month ORDER BY source_version, transaction_month) TO 'data/processed/sql_monthly_summary.csv' WITH (FORMAT CSV, HEADER TRUE)

\copy (SELECT 'v1' AS source_version, payment_method_id, payment_plan_days, COUNT(*) AS transaction_count, SUM(actual_amount_paid) AS transaction_record_amount FROM transactions_v1 GROUP BY payment_method_id, payment_plan_days UNION ALL SELECT 'v2' AS source_version, payment_method_id, payment_plan_days, COUNT(*) AS transaction_count, SUM(actual_amount_paid) AS transaction_record_amount FROM transactions_v2 GROUP BY payment_method_id, payment_plan_days ORDER BY source_version, payment_method_id, payment_plan_days) TO 'data/processed/sql_payment_plan_summary.csv' WITH (FORMAT CSV, HEADER TRUE)

\copy (SELECT 'v1' AS source_version, COUNT(*) AS transaction_count, COUNT(DISTINCT msno) AS distinct_user_count, COUNT(*) FILTER (WHERE is_auto_renew IS TRUE) AS auto_renew_record_count, ROUND(COUNT(*) FILTER (WHERE is_auto_renew IS TRUE)::numeric / NULLIF(COUNT(*), 0), 6) AS auto_renew_record_share, COUNT(*) FILTER (WHERE is_cancel IS TRUE) AS cancel_flag_record_count, ROUND(COUNT(*) FILTER (WHERE is_cancel IS TRUE)::numeric / NULLIF(COUNT(*), 0), 6) AS cancel_flag_record_share, SUM(actual_amount_paid) AS transaction_record_amount FROM transactions_v1 UNION ALL SELECT 'v2' AS source_version, COUNT(*) AS transaction_count, COUNT(DISTINCT msno) AS distinct_user_count, COUNT(*) FILTER (WHERE is_auto_renew IS TRUE) AS auto_renew_record_count, ROUND(COUNT(*) FILTER (WHERE is_auto_renew IS TRUE)::numeric / NULLIF(COUNT(*), 0), 6) AS auto_renew_record_share, COUNT(*) FILTER (WHERE is_cancel IS TRUE) AS cancel_flag_record_count, ROUND(COUNT(*) FILTER (WHERE is_cancel IS TRUE)::numeric / NULLIF(COUNT(*), 0), 6) AS cancel_flag_record_share, SUM(actual_amount_paid) AS transaction_record_amount FROM transactions_v2 ORDER BY source_version) TO 'data/processed/sql_version_profile.csv' WITH (FORMAT CSV, HEADER TRUE)
